const item=$input.first().json;
const raw=(item.output && String(item.output).trim().length)?String(item.output):'Hmm, não entendi direito — pode repetir? 😊';
const LIMIT=4000;
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function split(t,limit){ const chunks=[]; let rest=t; while(rest.length>limit){ let cut=rest.lastIndexOf('\n',limit); if(cut<limit*0.5) cut=rest.lastIndexOf(' ',limit); if(cut<limit*0.5) cut=limit; chunks.push(rest.slice(0,cut)); rest=rest.slice(cut).replace(/^\s+/,''); } if(rest.length) chunks.push(rest); return chunks; }
const parts=split(esc(raw),LIMIT);
return parts.map((p,i)=>({ json:{ messageText:p, partIndex:i+1, partTotal:parts.length } }));

function cortaEntrada(t){ t=String(t||''); return t.length>600 ? t.slice(0,600)+' […mensagem cortada aqui]' : t; }
