function personaBlock(pid,ctx){ const P=PPACK[pid]; return ['PERSONALIDADE OBRIGATÓRIA — '+P.nome+' ('+P.essencia+').','Esta personalidade é a coisa MAIS visível da sua resposta: alguém que leia sem contexto tem que conseguir dizer que foi o '+P.nome+' que escreveu.','VOZ: '+P.voz,'PALAVRAS TÍPICAS: '+P.lexico,'EMOJI: '+P.emoji,'GESTO DE ASSINATURA (obrigatório em TODA resposta): '+P.gesto,'NUNCA: '+P.proibido,(ctx==='teacher'?'O tom é do '+P.nome+', mas o CONTEÚDO da matéria continua completo, correto e sem cortes — a personalidade muda COMO você diz, jamais O QUE você ensina.':'')].filter(Boolean).join('\n'); }
