function looksLikeHelp(t){ var s=' '+String(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9? ]/g,' ').replace(/\s+/g,' ')+' '; if(!s.trim()) return false; var pats=[' qual e a resposta',' qual a resposta',' me da a resposta',' me de a resposta',' me diz a resposta',' diz a resposta',' fala a resposta',' responde por mim',' me responde',' nao sei',' nao entendi',' nao intendi',' me ajuda',' me ajude',' pode explicar',' explica',' explique',' como assim',' o que significa',' que significa',' como faz',' como eu faco',' tem dica',' me da uma dica',' da uma dica',' what is the answer',' tell me the answer',' i dont know',' i do not know',' help me',' pula',' pular',' proxima']; for(var i=0;i<pats.length;i++){ if(s.indexOf(pats[i])>=0) return true; } if(s.indexOf('?')>=0&&s.trim().split(' ').length>=3) return true; return false; }
