function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function clean(s){ return String(s||'').replace(/^[>\-\*\d\.\)\s]+/,'').replace(/[*_`#]/g,'').replace(/^\s*["“”']|["“”']\s*$/g,'').trim(); }
let res={ pkind:'explain', finalText:'', answer:'', sqlAns:'', parseFail:false };
if(eng.llmTask==='question'){
  const raw=out.replace(/\r/g,'');
  const lines=raw.split('\n').map(function(x){return x.trim();}).filter(Boolean);
  let qy='', a='';
  // 1) rotulos aceitos em varias formas: P:, Q:, Pergunta:, Question:, R:, A:, Resposta:, Answer:
  const RQ=/^[*_\s>\-\d\.\)]*(?:\**\s*)(p|q|pergunta|question|quest\u00e3o|questao)\s*[:\-\u2013]\s*/i;
  const RA=/^[*_\s>\-\d\.\)]*(?:\**\s*)(r|a|resposta|answer|gabarito)\s*[:\-\u2013]\s*/i;
  for(let i=0;i<lines.length;i++){ const ln=lines[i];
    if(!qy && RQ.test(ln)) qy=clean(ln.replace(RQ,''));
    else if(!a && RA.test(ln)) a=clean(ln.replace(RA,''));
  }
  // 2) fallback: duas linhas nao rotuladas
  if(!qy && lines.length) qy=clean(lines[0]);
  if(!a && lines.length>1) a=clean(lines[lines.length-1]);
  // 3) fallback: tudo numa linha so ("... R: xxx" ou "... - resposta: xxx")
  if(qy && !a){ const m=raw.match(/(?:\bR\s*[:\-]|\bresposta\s*[:\-]|\banswer\s*[:\-])\s*(.+)$/i); if(m) a=clean(m[1]); }
  if(a.length>60) a=a.split(/[.;\n]/)[0].trim();
