// Filtro Anti-Spoiler (deterministico).
// A v7.4 confia no LLM para nao revelar o gabarito de uma questao ainda aberta.
// Medido ao vivo: o prompt e explicito, o estado (q_answered=false) esta correto,
// e mesmo assim o modelo entrega a resposta quando o aluno pergunta "por que essa
// era a resposta certa?". Aqui a garantia deixa de depender de obediencia.
const eng = $('Professor Engine').first().json || {};
const ts = eng.teacher_state_new || {};
const ans = String(ts.answer || '').trim();
let out = String($json.output || '');
let mascarou = false;

// MARKDOWN: o envio e parse_mode HTML, entao ** e * chegam literais ao aluno.
// O prompt da duvida ja pede texto puro e o modelo desobedece (2/2 na medicao
// de 03/09), entao a garantia fica aqui, como a do spoiler. Roda ANTES do
// mascaramento para nao mexer no ___ que ele insere.
out = out
  .replace(/```+/g, '')
  .replace(/(\*\*|__)(?=\S)([\s\S]*?\S)\1/g, '$2')
  .replace(/(^|[^\w*])\*(?=\S)([^*\n]*?\S)\*(?!\w)/g, '$1$2')
  .replace(/^#{1,6}\s+/gm, '');

if (ans && ts.q_answered === false) {
  const esc = ans.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('(^|[^\\p{L}\\p{N}])(' + esc + ')(?![\\p{L}\\p{N}])', 'giu');
  const novo = out.replace(re, '$1___');
  if (novo !== out) { out = novo; mascarou = true; }
}
if (mascarou) {
  out += '\n\n😉 Segurei a resposta de proposito — tenta voce primeiro!';
}
return { json: Object.assign({}, $json, { output: out, antispoiler: mascarou }) };

