// ---------- normalizacao ----------
function semAcento(s){ return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,''); }
function deLeet(s){
  var map = {'0':'o','1':'i','3':'e','4':'a','5':'s','7':'t','8':'b','@':'a','$':'s','!':'i','|':'i'};
  return String(s||'').replace(/[0134578@$!|]/g, function(c){ return map[c]===undefined ? c : map[c]; });
}
// forma "achatada": minuscula, sem acento, sem leet, so letras
function achatar(s){ return deLeet(semAcento(String(s||'').toLowerCase())).replace(/[^a-z]/g,''); }
function sanitizeName(s){ return String(s||'').replace(/[^a-zA-Z\u00C0-\u024F\s'\-]/g,'').slice(0,50).trim(); }

// ---------- extracao do nome da frase ----------
function extractName(raw){
  var s = String(raw||'').trim();
  while (s.length && '.!?,'.indexOf(s.charAt(s.length-1))>=0) { s = s.slice(0,-1).trim(); }
  var low = semAcento(s.toLowerCase());
  var prefs = ['o meu nome eh ','o meu nome e ','meu nome eh ','meu nome e ','o nome e ','me chamo ','chamo-me ','chamo me ','me chame de ','pode me chamar de ','me chamam de ','meu apelido e ','nome: ','nome:','eu sou o ','eu sou a ','eu sou ','sou o ','sou a ','sou ','my name is ','i am ','call me ','eh ','e '];
  for (var i=0;i<prefs.length;i++){ if (low.indexOf(prefs[i])===0){ s = s.slice(prefs[i].length).trim(); break; } }
  var stop = ['e','de','da','do','dos','das','que','tenho','anos','ano','eu','meu','minha','nome','sou','um','uma','and','my','is'];
  var words = s.split(/\s+/).filter(function(w){ return w.length>0; });
  var out = [];
  for (var k=0;k<words.length;k++){
    var lw = semAcento(words[k].toLowerCase());
    if (stop.indexOf(lw)>=0) break;
    out.push(words[k]);
    if (out.length>=2) break;
  }
  return out.join(' ');
}

