function ehComum(cand){
  var tokens = String(cand||'').trim().split(/\s+/).map(achatar).filter(function(t){ return t.length>0; });
  if (!tokens.length) return false;
  for (var i=0;i<tokens.length;i++){ if (COMUNS.indexOf(tokens[i]) < 0) return false; }
  return true;
}

