function ofensivoCru(raw){
  var flat = achatar(raw);
  if (!flat) return null;
  if (PALAVRAO_EXATO.indexOf(flat) >= 0) return 'ofensivo';
  for (var c=0;c<PALAVRAO_CONTIDO.length;c++){ if (PALAVRAO_CONTIDO[c] && flat.indexOf(PALAVRAO_CONTIDO[c]) >= 0) return 'ofensivo'; }
  return null;
}

