  for (var i=0;i<tokens.length;i++){
    var t = tokens[i];
    if (SAUDACOES.indexOf(t) >= 0) return 'saudacao';
    if (PALAVRAO_EXATO.indexOf(t) >= 0) return 'ofensivo';
    if (LIXO.indexOf(t) >= 0) return 'nao_e_nome';
    if (t.length > 20) return 'nao_e_nome';
    var temVogal = false;
    for (var v=0; v<t.length; v++) { if (VOGAIS.indexOf(t.charAt(v)) >= 0) { temVogal = true; break; } }
    if (!temVogal) return 'nao_e_nome';                                // "xkcd", "hmm"
    if (/(.)\1\1/.test(t)) return 'nao_e_nome';                        // aaa, kkkk, ssss
    if (t.length >= 4 && /^(.{1,2})\1+$/.test(t)) return 'nao_e_nome'; // abab, xyxyxy
  }
  // frase inteira colada (ex.: "bom dia" -> "bomdia")
  if (SAUDACOES.indexOf(flat) >= 0) return 'saudacao';
  if (PALAVRAO_EXATO.indexOf(flat) >= 0) return 'ofensivo';
  if (LIXO.indexOf(flat) >= 0) return 'nao_e_nome';
  for (var c=0;c<PALAVRAO_CONTIDO.length;c++){ if (PALAVRAO_CONTIDO[c] && flat.indexOf(PALAVRAO_CONTIDO[c]) >= 0) return 'ofensivo'; }
  return null;
}

// ---------- montagem do veredito ----------
const tries = Number((d.profile && d.profile.name_tries) || 0);

// nome do Telegram como ultimo recurso, se ele mesmo passar na triagem
const fbRaw = sanitizeName(String(d.firstName || ''));
const fallback = (fbRaw && !ofensivoCru(d.firstName) && motivoRecusa(fbRaw) === null) ? fbRaw : 'Estudante';
const base = { tries: tries, fallback: fallback };

if (d.onboarding !== 'awaiting_name') { return { json: { ...d, nameCheck: { ...base, active: false } } }; }
if (d.type !== 'text') { return { json: { ...d, nameCheck: { ...base, active: true, verdict: 'reject', reason: 'nao_texto', candidate: '' } } }; }
if (d.isCommand) { return { json: { ...d, nameCheck: { ...base, active: true, verdict: 'reject', reason: 'comando', candidate: '' } } }; }

const cru = extractName(d.text);
const candidate = sanitizeName(cru);
const motivo = ofensivoCru(cru) || motivoRecusa(candidate);
let verdict, reason;
if (motivo) { verdict='reject'; reason=motivo; }
else if (ehComum(candidate)) { verdict='ok'; reason='lista_branca'; }  // atalho: nao gasta chamada de IA
else { verdict='ask_ai'; reason='incerto'; }

return { json: { ...d, nameCheck: { ...base, active: true, verdict: verdict, reason: reason, candidate: candidate, name: candidate } } };

// CAMADA 2: le a resposta do validador e devolve o veredito final.
// Falha da IA => aceita (fail-open): a camada 1 ja barrou o obvio e nao vale prender
// um usuario de nome incomum por causa de um 429 da Groq.
const d = $('Triagem de Nome').item.json;
const r = $input.item.json;
const nc = d.nameCheck || {};

let verdict = 'ok', reason = 'ia_indisponivel', name = nc.candidate || '';
try {
  // Gemini: candidates[0].content.parts[*].text. A forma da Groq fica como tolerancia
  // caso o no volte a apontar para la (fail-open cobre qualquer outra forma).
  const cand = r && r.candidates && r.candidates[0];
  const parts = cand && cand.content && cand.content.parts;
  const raw = Array.isArray(parts)
    ? parts.map(function (p) { return p && p.text ? p.text : ''; }).join('')
    : (r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : '');
  const m = String(raw || '').match(/\{[\s\S]*\}/);
  const j = m ? JSON.parse(m[0]) : null;
  if (j && j.valido === false) { verdict = 'reject'; reason = String(j.motivo || 'nao_e_nome'); }
  else if (j && j.valido === true) {
    verdict = 'ok'; reason = 'ia_ok';
    if (typeof j.nome === 'string' && j.nome.trim()) { name = j.nome.trim(); }
  }
} catch (e) { /* mantem o fail-open */ }

// a IA nunca pode injetar caractere fora do que o cadastro aceita
name = String(name).replace(/[^a-zA-Z\u00C0-\u024F\s'\-]/g, '').slice(0, 50).trim();
const letras = (name.match(/[a-zA-Z\u00C0-\u024F]/g) || []).length;
if (letras < 2) { verdict = 'reject'; reason = 'nao_e_nome'; }
if (reason !== 'saudacao' && reason !== 'ofensivo' && reason !== 'nao_e_nome' && verdict === 'reject') { reason = 'nao_e_nome'; }

return { json: { ...d, nameCheck: { ...nc, verdict: verdict, reason: reason, name: name, ia: true } } };
